result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/smoke.js", "content": "import { Sprite, SpriteMaterial, DataTexture, RGBAFormat, AdditiveBlending, Vector3 } from 'three';

/** Particle lifetime in seconds. */
export const LIFE = 3;

/**
 * Size curve: grows linearly from 0.3 to 1.5 over the particle's life.
 */
export function sizeAt(age, life = LIFE) {
  const t = age / life;
  return 0.3 + 1.2 * t;
}

/**
 * Opacity curve: quadratic fade-out, 0.7 at birth, exactly 0 at end of life.
 */
export function opacityAt(age, life = LIFE) {
  const t = Math.max(0, Math.min(1, age / life));
  const fade = 1 - t;
  return 0.7 * fade * fade;
}

/**
 * Deterministic PRNG (mulberry32).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Soft radial-gradient texture so the sprites look like puffballs, not squares. */
function makePuffTexture() {
  const N = 64;
  const data = new Uint8Array(N * N * 4);
  const r = (N - 1) / 2;
  for (let y = 0; y < N; y++) {
    for (let x = 0; x < N; x++) {
      const dx = (x - r) / r;
      const dy = (y - r) / r;
      const d = Math.sqrt(dx * dx + dy * dy);
      const a = Math.max(0, 1 - d);
      const i = (y * N + x) * 4;
      data[i] = 255;
      data[i + 1] = 255;
      data[i + 2] = 255;
      data[i + 3] = Math.round(255 * a * a);
    }
  }
  const tex = new DataTexture(data, N, N, RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

/**
 * Create a preallocated smoke-plume particle system.
 *
 * @param {object} [opts]
 * @param {number} [opts.max=120]       Pool size (all sprites created up front).
 * @param {number} [opts.rate=20]       Emission rate in particles/second.
 * @param {number} [opts.riseSpeed=1.2] Vertical speed in units/second.
 * @param {number} [opts.seed=1]        Seed for the deterministic lateral drift.
 */
export function createSmoke({ max = 120, rate = 20, riseSpeed = 1.2, seed = 1 } = {}) {
  const rng = mulberry32(seed);
  const texture = makePuffTexture();

  const sprites = [];
  const free = [];
  for (let i = 0; i < max; i++) {
    // Unique material per sprite so opacity can be driven independently.
    const material = new SpriteMaterial({
      map: texture,
      transparent: true,
      depthWrite: false,
      blending: AdditiveBlending,
      opacity: 0,
    });
    const sprite = new Sprite(material);
    sprite.visible = false;
    sprite.position.set(0, 0, 0);
    sprites.push(sprite);
    free.push(sprite);
  }

  return {
    sprites,   // every preallocated Sprite (identity-stable forever)
    free,      // LIFO pool of inactive sprites
    particles: [], // active: { sprite, age, life, driftX, driftZ }
    origin: new Vector3(0, 0, 0), // chimney mouth
    rate,
    riseSpeed,
    life: LIFE,
    spawnAcc: 0,
    rng,
    texture,
  };
}

function applyParticle(s, p) {
  p.sprite.scale.setScalar(sizeAt(p.age, p.life));
  p.sprite.material.opacity = opacityAt(p.age, p.life);
}

/**
 * Advance the simulation by dt seconds: spawn, integrate, expire.
 */
export function stepSmoke(s, dt) {
  // --- spawn ---
  s.spawnAcc += s.rate * dt;
  while (s.spawnAcc >= 1 && s.free.length > 0) {
    s.spawnAcc -= 1;
    const sprite = s.free.pop();
    const p = {
      sprite,
      age: 0,
      life: s.life,
      // seeded lateral drift around the plume axis
      driftX: (s.rng() * 2 - 1) * 0.18,
      driftZ: (s.rng() * 2 - 1) * 0.18,
    };
    sprite.position.copy(s.origin);
    applyParticle(s, p);
    sprite.visible = true;
    s.particles.push(p);
  }
  // Don't let unfulfilled spawn debt build into a burst when the pool refills.
  if (s.free.length === 0 && s.spawnAcc > 1) s.spawnAcc = 1;

  // --- integrate & expire ---
  for (let i = s.particles.length - 1; i >= 0; i--) {
    const p = s.particles[i];
    p.age += dt;
    if (p.age >= p.life) {
      p.sprite.material.opacity = 0;
      p.sprite.visible = false; // back to the pool
      s.particles.splice(i, 1);
      s.free.push(p.sprite);
    } else {
      p.sprite.position.y += s.riseSpeed * dt;
      p.sprite.position.x += p.driftX * dt;
      p.sprite.position.z += p.driftZ * dt;
      applyParticle(s, p);
    }
  }
}
"})
