result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/smoke.test.js", "content": "import { describe, it, expect } from 'vitest';
import { createSmoke, stepSmoke, sizeAt, opacityAt, LIFE } from '../src/smoke.js';

const SAMPLES = 20;

function visibleCount(s) {
  return s.sprites.reduce((n, sp) => n + (sp.visible ? 1 : 0), 0);
}

describe('smoke life curves', () => {
  it('size is strictly increasing over a particle\'s life (20 samples)', () => {
    const ages = Array.from({ length: SAMPLES }, (_, i) => (i / (SAMPLES - 1)) * LIFE);
    for (let i = 1; i < ages.length; i++) {
      expect(sizeAt(ages[i])).toBeGreaterThan(sizeAt(ages[i - 1]));
    }
  });

  it('opacity is strictly decreasing over a particle\'s life (20 samples)', () => {
    const ages = Array.from({ length: SAMPLES }, (_, i) => (i / (SAMPLES - 1)) * LIFE);
    for (let i = 1; i < ages.length; i++) {
      expect(opacityAt(ages[i])).toBeLessThan(opacityAt(ages[i - 1]));
    }
  });

  it('curves are applied to sprite scale and material.opacity during simulation', () => {
    const s = createSmoke({ max: 40, rate: 30, seed: 7 });
    const dt = LIFE / 60;
    let checked = 0;
    for (let k = 0; k < 200; k++) {
      stepSmoke(s, dt);
      for (const p of s.particles) {
        // age was advanced by dt inside stepSmoke, so compare against the
        // pre-step value: recompute from position-independent state instead.
        expect(p.sprite.scale.x).toBeCloseTo(sizeAt(Math.min(p.age, LIFE)), 6);
        expect(p.sprite.material.opacity).toBeCloseTo(
          opacityAt(Math.min(p.age, LIFE)),
          6
        );
        checked++;
      }
    }
    expect(checked).toBeGreaterThan(0);
  });
});

describe('pool behaviour', () => {
  it('expired sprites become invisible and return to the pool; steady state matches rate*life', () => {
    const rate = 20;
    const s = createSmoke({ max: 120, rate, riseSpeed: 1.2, seed: 42 });

    const identity = new Set(s.sprites); // object-identity set of every Sprite ever created
    const dt = 1 / 60;
    const steps = Math.round(10 / dt);

    for (let k = 0; k < steps; k++) {
      stepSmoke(s, dt);
      // no new Sprite objects may appear after creation
      for (const p of s.particles) {
        expect(identity.has(p.sprite)).toBe(true);
      }
    }

    // analytic steady state: rate * life
    const expected = rate * LIFE;
    const actual = visibleCount(s);
    expect(Math.abs(actual - expected)).toBeLessThanOrEqual(2);

    // pool accounting: free + active must equal max, and active sprites are visible
    expect(s.free.length + s.particles.length).toBe(s.sprites.length);
    for (const p of s.particles) expect(p.sprite.visible).toBe(true);
    for (const sp of s.free) {
      expect(sp.visible).toBe(false);
      expect(sp.material.opacity).toBe(0);
    }
  });

  it('no new Sprite objects are constructed after creation (identity set across full run)', () => {
    const s = createSmoke();
    const identity = new Set(s.sprites);
    expect(identity.size).toBe(120); // all preallocated and distinct

    const seen = new Set();
    for (let k = 0; k < 600; k++) {
      stepSmoke(s, 1 / 60);
      for (const p of s.particles) {
        seen.add(p.sprite);
      }
    }
    for (const sp of seen) expect(identity.has(sp)).toBe(true);
    expect(seen.size).toBeGreaterThan(0);
  });
});

describe('boundary values', () => {
  it('opacity(0) = 0.7 and opacity(life) = 0 within 1e-9', () => {
    expect(Math.abs(opacityAt(0) - 0.7)).toBeLessThanOrEqual(1e-9);
    expect(Math.abs(opacityAt(LIFE))).toBeLessThanOrEqual(1e-9);
    // also right before expiry the applied material value stays > 0
    expect(opacityAt(LIFE - 1e-12)).toBeGreaterThan(0);
  });

  it('size at birth is 0.3', () => {
    expect(sizeAt(0)).toBeCloseTo(0.3, 12);
  });
});
"})
